  JOIN policy_jp.sources s ON s.url = 'https://www.soumu.go.jp/main_content/000925835.xlsx'
  JOIN policy_jp.sources c ON c.url = 'https://www.soumu.go.jp/main_content/000885088.pdf'
ON CONFLICT (lg_code) DO NOTHING;

-- 自我檢查：筆數與種類分布跟產生時一樣（少灌、多灌都讓這支 migration 失敗）
DO $$
DECLARE got TEXT;
BEGIN
  SELECT string_agg(kind || ' ' || n, '、' ORDER BY kind) INTO got
    FROM (SELECT kind, count(*) AS n FROM policy_jp.lg_code_registry WHERE as_of = DATE '2024-01-01' GROUP BY kind) t;
  IF got IS DISTINCT FROM 'admin_ward 171、city 710、core_city 62、designated_city 20、prefecture 47、special_ward 23、town 743、village 189' THEN
    RAISE EXCEPTION 'lg_code_registry 的分布不對：%（預期 admin_ward 171、city 710、core_city 62、designated_city 20、prefecture 47、special_ward 23、town 743、village 189）', got;
  END IF;
END
$$;
